from contextlib import contextmanager


@contextmanager
def non_suppressing_lock():
    yield


def bounded_retry(fail):
    for attempt in range(3):
        if not fail:
            return 'success'
        if attempt == 2:
            raise OSError('last attempt')


def return_inside_lock(early):
    with non_suppressing_lock():
        if early: return 'early'
        return 'normal'


def raise_inside_lock(fail):
    with non_suppressing_lock():
        if fail: raise OSError('expected failure')
        return 'normal'
